const COLD_CONDUCTIVITY: u32 = 1u;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }

// Extract material (bits 0-7) and thermal (bits 8-15) together
fn get_mat_thermal(p: u32) -> vec2<u32> {
    let low16 = p & 0xFFFFu;  // Extract lower 16 bits
    return vec2<u32>(low16 & 0xFFu, (low16 >> 8u) & 0xFFu);
}

fn get_thermal(p: u32) -> u32 { 
    return (p >> THERMAL_SHIFT) & THERMAL_MASK; 
}

fn set_thermal(p: u32, t: u32) -> u32 {
    return (p & ~(THERMAL_MASK << THERMAL_SHIFT)) | ((t & THERMAL_MASK) << THERMAL_SHIFT);
}

fn conductivity_of(mat: u32) -> u32 {
    return cold_table[mat * COLD_STRIDE + COLD_CONDUCTIVITY];
}

// Optimized harmonic mean using precomputed 2*a
fn harmonic_mean_fast(a_2x: u32, b: u32) -> u32 {
    let s = (a_2x >> 1u) + b;  // a + b
    if (s == 0u) { return 0u; }
    return (a_2x * b) / s;
}

