        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx - GRID_WIDTH]);
    }

    // South
    if (y < GRID_HEIGHT - 1u) {
        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx + GRID_WIDTH]);
    }

    // West
    if (x > 0u) {
        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx - 1u]);
    }

    // East
    if (x < GRID_WIDTH - 1u) {
        delta += compute_exchange(self_thermal, self_cond_2x, grid_in[idx + 1u]);
    }

    // Apply delta with saturating arithmetic
    let new_thermal = i32(self_thermal) + delta;
    let clamped = u32(max(0, min(255, new_thermal)));
    grid_out[idx] = set_thermal(voxel, clamped);
}

